final class MewV2CompositionTest { static void run(){var r=RomProfile.FIRE_RED_EN_10;var a=MewBattleCore.build(r);var x=MewBattleCoreExtension.layout(r);var b=MewEventDataCore.build(r);require(a.bytes().length==448,"A base size");require(x.dispatcherOffset()+x.dispatcherBytes().length<=MewBattleCore.SCRATCH_RELATIVE,"A extension before ball scratch");require(b.bytes().length<=MewEventDataCore.CAPACITY,"B fits SB1");require(MewFinalEventPreset.build(r).payloadBytes()<=RamScript.SCRIPT_SIZE,"event fits WC");require((r.stringVar4+0x100L)==CpuSetNativeHelperInstaller.helperDestination(r.stringVar4+0xC0L),"bridge at +0x100");require((r.stringVar4+0x140L)==CpuSetNativeHelperInstaller.helperDestination(r.stringVar4+0x100L),"Probe24 stage at +0x140");byte[] mewCb=new ObjectEventRamScriptBinding(PersistentEventMewRecoveryProbePreset.MEW_HOST).continuationCallback(r,0);require((mewCb[2]&0xFF)==0x0B && (mewCb[3]&0xFF)==0x20,"final battle continuation must resolve localId 11, not Stan localId 8");}private static void require(boolean v,String m){if(!v)throw new AssertionError(m);} }
